# api/views.py - Django REST Framework view for image processing
import ctypes
import os
import mmap
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.parsers import MultiPartParser
from django.conf import settings

# Native library for high-performance image thumbnail generation
_lib = ctypes.CDLL(os.path.join(settings.BASE_DIR, 'native', 'libthumb.so'))

# void* create_buffer(size_t size)
_lib.create_buffer.restype = ctypes.c_void_p
_lib.create_buffer.argtypes = [ctypes.c_size_t]

# int process_image(void* buf, const char* data, size_t len)
_lib.process_image.restype = ctypes.c_int
_lib.process_image.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_size_t]

# void release_buffer(void* buf)
_lib.release_buffer.restype = None
_lib.release_buffer.argtypes = [ctypes.c_void_p]

# void get_thumbnail(void* buf, char* out, size_t* out_len)
_lib.get_thumbnail.restype = None
_lib.get_thumbnail.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.POINTER(ctypes.c_size_t)]


class ThumbnailView(APIView):
    parser_classes = [MultiPartParser]

    def post(self, request, format=None):
        """Generate thumbnail from uploaded image."""
        uploaded = request.FILES.get('image')
        if not uploaded:
            return Response({'error': 'No image provided'}, status=400)

        if uploaded.size > 10 * 1024 * 1024:  # 10MB limit
            return Response({'error': 'File too large'}, status=413)

        raw_data = uploaded.read()
        buf = None

        try:
            # Allocate native buffer
            buf = _lib.create_buffer(len(raw_data))
            if not buf:
                return Response({'error': 'Memory allocation failed'}, status=500)

            # Process the image data
            result = _lib.process_image(buf, raw_data, len(raw_data))

            if result != 0:
                # On error, free the buffer and return error
                _lib.release_buffer(buf)
                buf = None  # Mark as freed

                # Attempt recovery with smaller allocation
                if result == -2:  # RESIZE_NEEDED error code
                    buf = _lib.create_buffer(len(raw_data) // 2)
                    if buf:
                        result = _lib.process_image(buf, raw_data, len(raw_data) // 2)
                        if result != 0:
                            _lib.release_buffer(buf)
                            return Response({'error': 'Processing failed after retry'}, status=500)
                    else:
                        return Response({'error': 'Recovery allocation failed'}, status=500)
                else:
                    return Response({'error': f'Processing error: {result}'}, status=500)

            # Extract thumbnail
            out_buf = ctypes.create_string_buffer(1024 * 1024)  # 1MB output buffer
            out_len = ctypes.c_size_t(0)
            _lib.get_thumbnail(buf, out_buf, ctypes.byref(out_len))

            thumbnail_data = out_buf.raw[:out_len.value]

            return Response({
                'thumbnail': thumbnail_data.hex(),
                'size': out_len.value
            })

        except Exception as e:
            return Response({'error': f'Internal error: {str(e)}'}, status=500)

        finally:
            # Cleanup: always free the buffer
            if buf:
                _lib.release_buffer(buf)


class BatchThumbnailView(APIView):
    parser_classes = [MultiPartParser]

    def post(self, request, format=None):
        """Process multiple images concurrently using shared memory."""
        images = request.FILES.getlist('images')
        if not images:
            return Response({'error': 'No images provided'}, status=400)

        results = []
        buffers = []

        try:
            for img in images[:5]:  # Max 5 images
                raw = img.read()
                buf = _lib.create_buffer(len(raw))
                if buf:
                    buffers.append(buf)
                    rc = _lib.process_image(buf, raw, len(raw))
                    if rc == 0:
                        out = ctypes.create_string_buffer(512 * 1024)
                        out_len = ctypes.c_size_t(0)
                        _lib.get_thumbnail(buf, out, ctypes.byref(out_len))
                        results.append({'size': out_len.value, 'status': 'ok'})
                    else:
                        results.append({'status': 'error', 'code': rc})
                else:
                    results.append({'status': 'alloc_failed'})

            return Response({'results': results})

        finally:
            for b in buffers:
                _lib.release_buffer(b)
